ALTER TABLE ONLY public.bug_reports
    ADD CONSTRAINT bug_reports_pkey PRIMARY KEY (id);


--
-- Name: idx_bug_hnsw; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_bug_hnsw ON public.bug_reports USING hnsw (embedding public.vector_cosine_ops) WITH (m='16', ef_construction='64');


--
-- Name: idx_bug_ivfflat; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_bug_ivfflat ON public.bug_reports USING ivfflat (embedding public.vector_cosine_ops) WITH (lists='10');


--
-- Name: idx_bug_product_component; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_bug_product_component ON public.bug_reports USING btree (product, component);


--
-- Name: idx_bug_status; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_bug_status ON public.bug_reports USING btree (resolution_status);


--
-- Name: bug_reports bug_reports_updated_at; Type: TRIGGER; Schema: public; Owner: postgres
--

CREATE TRIGGER bug_reports_updated_at BEFORE UPDATE ON public.bug_reports FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();


